   114→public sealed class IntrinsicGasTxValidator : ITxValidator
   115→{
   116→    public static readonly IntrinsicGasTxValidator Instance = new();
   117→    private IntrinsicGasTxValidator() { }
   118→
   119→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec)
   120→    {
   121→        // This is unnecessarily calculated twice - at validation and execution times.
   122→        IntrinsicGas intrinsicGas = IntrinsicGasCalculator.Calculate(transaction, releaseSpec);
   123→        return transaction.GasLimit < intrinsicGas.MinimalGas
   124→            ? TxErrorMessages.IntrinsicGasTooLow
   125→            : ValidationResult.Success;
   126→    }
   127→}
